t = input().strip()

if '*' not in s:
    # No wildcard, check if exactly equal
    if s == t:
        print("YES")
    else:
        print("NO")
else:
    # There is a wildcard
    star_pos = s.index('*')
    part_before = s[:star_pos]
    part_after = s[star_pos+1:]

    # Check if parts match the beginning and end of t
    if t.startswith(part_before) and t.endswith(part_after):
        # Check if the remaining part can be filled by the wildcard
        # The wildcard can be empty, so we just need to check if the lengths work
        # len(t) should be at least len(part_before) + len(part_after)
        if len(t) >= len(part_before) + len(part_after):
            print("YES")
        else:
            print("NO")
    else:
        print("NO")
