import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Compute prefix counts
    prefix_count = [0] * n
    count = {}
    for i in range(n):
        val = a[i]
        if val in count:
            prefix_count[i] = count[val]
        else:
            prefix_count[i] = 0
        count[val] = prefix_count[i] + 1

    # Compute suffix counts
    suffix_count = [0] * n
    count = {}
    for j in range(n-1, -1, -1):
        val = a[j]
        if val in count:
            suffix_count[j] = count[val]
        else:
            suffix_count[j] = 0
        count[val] = suffix_count[j] + 1

    # Count valid pairs
    result = 0
    for i in range(n):
        for j in range(i+1, n):
            if prefix_count[i] > suffix_count[j]:
                result += 1

    print(result)

if __name__ == "__main__":
    solve()
"}

