def digit_sum(x):
    """Calculate the sum of digits of x"""
    return sum(int(d) for d in str(x))

def solve(a, b, c):
    solutions = []

    # Try all possible values of s(x) (sum of digits)
    for s in range(1, 82):  # s can be at most 9*9 = 81
        # Calculate x from the equation x = b*s^a + c
        x = b * (s ** a) + c

        # Check if x is a valid solution
        if 0 < x < 10**9 and digit_sum(x) == s:
            solutions.append(x)

    return solutions

def main():
    # Read input
    a, b, c = map(int, input().split())

    # Solve
    solutions = solve(a, b, c)

    # Output
    print(len(solutions))
    if solutions:
        print(' '.join(map(str, sorted(solutions))))

if __name__ == "__main__":
    main()
"}

