        found = False
        for s in [chr(ord('a') + i) for i in range(26)] * m:
            # Check if s works for all strings
            valid = True
            for a in strings:
                diff = 0
                for i in range(m):
                    if s[i] != a[i]:
                        diff += 1
                        if diff > 1:
                            break
                if diff > 1:
                    valid = False
                    break

            if valid:
                results.append(s)
                found = True
                break

        if not found:
            results.append("-1")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
