    grid = [input().strip() for _ in range(n)]

    min_cost = float('inf')

    # Try all possible k values from 2 to min(n, m)
    for k in range(2, min(n, m) + 1):
        # Calculate padded dimensions
        rows = (n + k - 1) // k * k
        cols = (m + k - 1) // k * k

        # Calculate cost
        cost = 0
        for i in range(0, rows, k):
            for j in range(0, cols, k):
                # Count 0s and 1s in this block
                zero_count = 0
                one_count = 0
                for di in range(k):
                    for dj in range(k):
                        # Check if we are within bounds of original grid
                        if i + di < n and j + dj < m:
                            if grid[i + di][j + dj] == '0':
                                zero_count += 1
                            else:
                                one_count += 1
                        else:
                            # Padded with 0s
                            zero_count += 1

                # Choose minimum cost for this block
                cost += min(zero_count, one_count)

        min_cost = min(min_cost, cost)

    print(min_cost)

