def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read the image
    image = []
    idx = 2
    for i in range(n):
        image.append(data[idx])
        idx += 1

    min_toggles = float('inf')

    # Try all possible k values
    for k in range(2, min(n, m) + 1):
        # Calculate padded dimensions
        new_n = ((n + k - 1) // k) * k
        new_m = ((m + k - 1) // k) * k

        # Pad the image with zeros
        padded = []
        for row in image:
            padded.append(row + '0' * (new_m - m))
        for _ in range(new_n - n):
            padded.append('0' * new_m)

        # Calculate toggles for this k
        toggles = 0
        for i in range(0, new_n, k):
            for j in range(0, new_m, k):
                # Count 0s and 1s in this k x k block
                count_0 = 0
                count_1 = 0
                for di in range(k):
                    for dj in range(k):
                        if padded[i + di][j + dj] == '0':
                            count_0 += 1
                        else:
                            count_1 += 1

                # Minimum toggles to make this block uniform
                toggles += min(count_0, count_1)

        min_toggles = min(min_toggles, toggles)

    print(min_toggles)

if __name__ == '__main__':
    solve()
