from itertools import permutations

def is_super_lucky(num_str):
    count_4 = num_str.count('4')
    count_7 = num_str.count('7')
    return count_4 == count_7

def generate_super_lucky_numbers():
    # Generate numbers with increasing lengths (must be even)
    length = 2
    while True:
        # Generate all combinations of 4s and 7s with equal counts
        for count_4 in range(length // 2 + 1):
            count_7 = length - count_4
            if count_4 != count_7:
                continue

            # Generate all unique permutations
            digits = ['4'] * count_4 + ['7'] * count_7
            unique_perms = set(permutations(digits))

            # Convert to strings and yield
            for perm in unique_perms:
                yield ''.join(perm)

        length += 2

def solve():
    n = input().strip()

    # Generate super lucky numbers in increasing order
    for num_str in generate_super_lucky_numbers():
        # Compare strings lexicographically after padding with leading zeros
        if len(num_str) < len(n):
            continue
        if len(num_str) > len(n):
            print(num_str)
            return
        if num_str >= n:
            print(num_str)
            return

solve()
