def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    s = data[2]

    # Convert string to list of character positions (0-25)
    chars = [ord(c) - ord('a') for c in s]

    # Try to find a valid string s' using backtracking
    def backtrack(index, total_distance, result):
        if index == n:
            if total_distance == k:
                return result[:]
            return None

        # Try all possible characters for position index
        for c in range(26):
            dist = abs(c - chars[index])
            if total_distance + dist <= k:
                result[index] = c
                res = backtrack(index + 1, total_distance + dist, result)
                if res is not None:
                    return res
            # If we can't reach k by changing to this character, skip
        return None

    result = chars.copy()
    solution = backtrack(0, 0, result)

    if solution is None:
        print(-1)
    else:
        # Convert back to characters and print
        print(''.join([chr(c + ord('a')) for c in solution]))

solve()
