import sys

def is_consecutive(s, t):
    """Check if s and t are consecutive in lexicographic order"""
    # Find the first position where they differ
    for i in range(len(s)):
        if s[i] != t[i]:
            # Check if they are consecutive
            if ord(t[i]) - ord(s[i]) == 1 and all(s[j] == t[j] for j in range(i)):
                return True
            return False
    return False

def find_middle_string(s, t):
    """Find a string that is lexicographically between s and t"""
    # Check if they are consecutive
    if is_consecutive(s, t):
        return "No such string"

    # Find the first position where s[i] < t[i]
    for i in range(len(s)):
        if s[i] < t[i]:
            # Increment s at this position
            new_s = s[:i] + chr(ord(s[i]) + 1) + s[i+1:]
            return new_s

    # This shouldn't happen because s < t
    return "No such string"

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    result = find_middle_string(s, t)
    print(result)
