import sys
from math import factorial
from collections import Counter

def count_valid_numbers(n):
    digits = list(str(n))
    freq = Counter(digits)
    total = 0

    # Count all permutations of all digits
    total_digits = len(digits)
    total_permutations = factorial(total_digits)
    for digit, count in freq.items():
        total_permutations //= factorial(count)

    # Count permutations starting with 0
    if '0' in freq:
        remaining_digits = total_digits - 1
        permutations_starting_with_0 = factorial(remaining_digits)
        for digit, count in freq.items():
            if digit == '0':
                permutations_starting_with_0 //= factorial(count - 1)
            else:
                permutations_starting_with_0 //= factorial(count)
        total -= permutations_starting_with_0

    return total

def main():
    n = sys.stdin.readline().strip()
    print(count_valid_numbers(n))

if __name__ == "__main__":
    main()
