    c1 = list(map(int, input().split()))
    c2 = list(map(int, input().split()))
    c3 = list(map(int, input().split()))

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    # Try all 3 colors for root
    for root_color in range(1, 4):
        # Try all 3 colors for the first child
        for child_color in range(1, 4):
            if child_color == root_color:
                continue

            # DFS to assign colors
            color = [-1] * n
            color[0] = root_color
            stack = [(0, -1)]  # (vertex, parent)
            valid = True

            while stack and valid:
                v, parent = stack.pop()

                # Find a valid color for v
                valid_color = None
                for c in range(1, 4):
                    if c != color[parent] and c != color[v]:
                        valid_color = c
                        break

                if valid_color is None:
                    valid = False
                    break

                color[v] = valid_color

                # Push children
                for neighbor in adj[v]:
                    if neighbor != parent:
                        stack.append((neighbor, v))

            if valid:
