n = int(input())

# We can transform a into b if there exists an integer x with 1 < |x| such that a * x = b or b * x = a
# This means we can transform a into b if |b| % |a| == 0 and |b| / |a| > 1
# Or |a| % |b| == 0 and |a| / |b| > 1

# We want to maximize the score by picking transformations
# We can pick either a -> b or b -> a if the condition is satisfied in at least one direction

# Initialize score
score = 0

# Try all possible pairs
for a in range(-n, n + 1):
    if a == 0:
        continue
    for b in range(-n, n + 1):
        if b == 0 or a == b:
            continue

        # Check if we can transform a -> b
        can_transform_a_to_b = False
        can_transform_b_to_a = False

        # Check if b is a multiple of a
        if abs(b) % abs(a) == 0:
            quotient = abs(b) / abs(a)
            if quotient > 1:
                can_transform_a_to_b = True

        # Check if a is a multiple of b
        if abs(a) % abs(b) == 0:
            quotient = abs(a) / abs(b)
            if quotient > 1:
                can_transform_b_to_a = True

        # If at least one direction is valid, we can do this transformation
        if can_transform_a_to_b or can_transform_b_to_a:
            # We want to maximize score, so we pick the direction that gives us the highest score
            # The score is the absolute value of the quotient
            if can_transform_a_to_b and can_transform_b_to_a:
                # Both directions are valid, pick the one with higher score
                if abs(b) / abs(a) > abs(a) / abs(b):
                    score += abs(b) / abs(a)
                else:
                    score += abs(a) / abs(b)
            else:
                if can_transform_a_to_b:
                    score += abs(b) / abs(a)
                else:
                    score += abs(a) / abs(b)

print(score)
