def solve():
    n, m, w = map(int, input().split())
    weights = list(map(int, input().split()))
    beauties = list(map(int, input().split()))

    # Find friendship groups using Union-Find
    parent = list(range(n + 1))  # 1-indexed

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        parent[find(x)] = find(y)

    for _ in range(m):
        x, y = map(int, input().split())
        union(x, y)

    # Group Hoses by their root
    from collections import defaultdict
    groups = defaultdict(list)
    for i in range(1, n + 1):
        root = find(i)
        groups[root].append(i - 1)  # 0-indexed

    # For each group, calculate total weight and list of individual items
    group_options = []
    for group in groups.values():
        total_weight = sum(weights[i] for i in group)
        total_beauty = sum(beauties[i] for i in group)

        # Option 1: Take the whole group
        if total_weight <= w:
            group_options.append((total_weight, total_beauty))

        # Option 2: Take at most one from the group
        items = [(weights[i], beauties[i]) for i in group]
        group_options.append(items)

    # Knapsack DP
    dp = [0] * (w + 1)

    for option in group_options:
        if isinstance(option, list):  # This is the 'take at most one' option
            # Regular 0-1 knapsack
            for j in range(w, -1, -1):
                for weight, beauty in option:
                    if j >= weight:
                        dp[j] = max(dp[j], dp[j - weight] + beauty)
        else:  # This is the 'take whole group' option
            weight, beauty = option
            if weight <= w:
                for j in range(weight, w + 1):
                    dp[j] = max(dp[j], dp[j - weight] + beauty)

    print(max(dp))

solve()
