    input = sys.stdin.read().split()

    idx = 0
    n = int(input[idx]); idx += 1
    m = int(input[idx]); idx += 1
    w = int(input[idx]); idx += 1

    weights = list(map(int, input[idx:idx+n]))
    idx += n
    beauties = list(map(int, input[idx:idx+n]))
    idx += n

    # Union-Find to find friendship groups
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    for _ in range(m):
        x = int(input[idx]) - 1; idx += 1
        y = int(input[idx]) - 1; idx += 1
        union(x, y)

    # Group by root and collect all members for each group
    groups = []
    visited = [False] * n

    for i in range(n):
        if visited[i] is False:
            root = find(i)
            group = []
            for j in range(n):
                if find(j) == root and not visited[j]:
                    visited[j] = True
                    group.append(j)
            groups.append(group)

    # 0-1 knapsack with at most one item per group
    dp = [0] * (w + 1)

