def modinv(a, mod):
    """Compute modular inverse using Fermat's little theorem"""
    return pow(a, mod - 2, mod)

def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Probability that S1 > S2
    prob = 1

    for i in range(n):
        ai = a[i]
        bi = b[i]

        if ai != 0 and bi != 0:
            # Both fixed
            if ai > bi:
                # Always greater
                prob = prob * 1 % MOD
            elif ai < bi:
                # Never greater
                prob = 0
            else:
                # Equal, continue
                prob = prob * 1 % MOD
        elif ai != 0:
            # ai fixed, bi erased
            if ai > bi:
                # Always greater
                prob = prob * 1 % MOD
            elif ai < bi:
                # Never greater
                prob = 0
            else:
                # ai == bi, probability 1/2
                prob = prob * modinv(2, MOD) % MOD
        elif bi != 0:
            # ai erased, bi fixed
            if ai > bi:
                # Probability 1/2
                prob = prob * modinv(2, MOD) % MOD
            elif ai < bi:
                # Never greater
                prob = 0
            else:
                # ai == bi, probability 1/2
                prob = prob * modinv(2, MOD) % MOD
        else:
            # Both erased
            # Probability a > b = (m-1)/2m
            prob = prob * modinv(2 * m, MOD) % MOD

