    color = [-1] * (n + 1)
    for start in range(1, n + 1):
        if color[start] == -1:
            queue = [start]
            color[start] = 0
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False, None
    return True, color

