        mid = (l + r) // 2
        node.left = build(arr, l, mid)
        node.right = build(arr, mid+1, r)
        node.first = node.left.first
        node.last = node.right.last
        node.candies = node.left.candies + node.right.candies
        if node.left.last + node.right.first >= 10:
            node.candies += 1
        node.compressed = (node.left.compressed + node.right.compressed) % 10
        return node

    def query(node, l, r, ql, qr):
        # Identity for empty segment
        if not node:
