    # Precompute smallest prime factor for all numbers
    def smallest_prime_factors(limit):
        spf = list(range(limit + 1))
        for i in range(2, int(limit**0.5) + 1):
            if spf[i] == i:
                for j in range(i * i, limit + 1, i):
                    if spf[j] == j:
                        spf[j] = i
        return spf

    # For each good pair, count maximum operations
    count = 0
    for _ in range(m):
        i = int(next(it)) - 1
        j = int(next(it)) - 1

        x = a[i]
        y = a[j]

        # Function to count maximum operations for a pair
        def count_operations(x, y):
            operations = 0
            # While both numbers are greater than 1
            while x > 1 and y > 1:
