import sys

def is_good(table, kept_columns):
    """Check if the table is good with only kept_columns."""
    n = len(table)
    m = len(table[0])

    # Create the projected table
    projected = []
    for row in table:
        projected_row = ''.join([row[i] for i in kept_columns])
        projected.append(projected_row)

    # Check lexicographic order
    for i in range(n - 1):
        if projected[i] > projected[i + 1]:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    table = []
    idx = 2
    for _ in range(n):
        row = data[idx:idx + m]
        table.append(row)
        idx += m

    # Try all possible subsets of columns
    max_kept = 0
    for mask in range(1 << m):
        # Find which columns to keep
        kept_columns = []
        for i in range(m):
            if mask & (1 << i):
                kept_columns.append(i)

        # Check if this subset makes the table good
        if is_good(table, kept_columns):
            max_kept = max(max_kept, len(kept_columns))

    print(m - max_kept)

if __name__ == "__main__":
