import sys

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def kruskal(n, edges):
    edges.sort(key=lambda x: x[2])
    parent = list(range(n + 1))
    rank = [1] * (n + 1)
    mst_edges = []

    for a, b, e in edges:
        if union(parent, rank, a, b):
            mst_edges.append((a, b, e))
            if len(mst_edges) == n - 1:
                break

    # Build MST tree
    tree = [[] for _ in range(n + 1)]
    for a, b, e in mst_edges:
        tree[a].append((b, e))
        tree[b].append((a, e))

    return tree, mst_edges

# Function to find max edge weight on path from u to v in tree
def max_edge_on_path(tree, u, v):
    # Use BFS to find path and track max edge
    from collections import deque

    visited = {u: None}
    queue = deque([u])

    while queue:
        node = queue.popleft()
        if node == v:
            break
        for neighbor, weight in tree[node]:
            if neighbor not in visited:
                visited[neighbor] = (node, weight)
                queue.append(neighbor)

    # Reconstruct path and find max weight
    path = []
    current = v
    while current is not None:
        path.append(current)
        current = visited[current][0]

    max_weight = 0
    for i in range(len(path) - 1):
        prev = path[i]
        curr = path[i + 1]
        # Find weight between prev and curr
        for neighbor, weight in tree[prev]:
            if neighbor == curr:
                max_weight = max(max_weight, weight)
                break

    return max_weight

# Main
if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

    it = iter(data)
    n = int(next(it))
