        a = int(next(it))
        b = int(next(it))
        e = int(next(it))
        edges.append((a, b, e))

    tree, mst_edges_set = kruskal(n, edges)

    # Find which edges are not in MST
    mst_set = set(mst_edges_set)

    # Process non-MST edges
    for a, b, e in edges:
        if (a, b, e) not in mst_set and (b, a, e) not in mst_set:
