    n = int(input())
    s = input()

    # Count parentheses
    open_count = s.count('(')
    close_count = n - open_count

    # If not equal, impossible
    if open_count != close_count:
        print(-1)
        return

    # Traverse to find bad segments
    balance = 0
    total_time = 0
    start_bad = -1

    for i in range(n):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1

        # If balance is negative, we need to fix it
        if balance < 0:
            if start_bad == -1:
                start_bad = i
        else:
            # If balance is non-negative, check if we were in a bad segment
            if start_bad != -1:
                # End of bad segment at i-1
                total_time += i - start_bad
                start_bad = -1

    # Check if there's an open bad segment after loop
    if start_bad != -1:
        total_time += n - start_bad

    print(total_time)

