def find_middle_string(s, t):
    # Find the first position where s and t differ
    for i in range(len(s)):
        if s[i] != t[i]:
            # Check if there's a character between s[i] and t[i]
            if ord(s[i]) + 1 < ord(t[i]):
                # Construct the middle string
                middle = s[:i] + chr(ord(s[i]) + 1) + 'a' * (len(s) - i - 1)
                return middle
            else:
                # Check if we can increment a character in the prefix
                # Try to find a character in the prefix that can be incremented
                for j in range(i):
                    if ord(s[j]) < ord('z'):
                        # Increment the character at position j
                        middle = s[:j] + chr(ord(s[j]) + 1) + 'a' * (i - j - 1) + s[i:] + 'a' * (len(s) - i)
                        return middle
                # If we can't increment any character in the prefix, return None
                return None
    # If s and t are identical, which shouldn't happen
    return None

