def is_subsequence(s1, s2):
    """Check if s2 is a subsequence of s1 repeated multiple times"""
    i = 0  # pointer for s2
    j = 0  # pointer for s1
    while i < len(s2):
        if j == len(s1):
            # Need to wrap around to the start of s1
            j = 0
        if s1[j] == s2[i]:
            i += 1
        j += 1
    return i == len(s2)

def solve():
    s1 = input().strip()
    s2 = input().strip()

    # Check if all characters in s2 are in s1
    if not set(s2).issubset(set(s1)):
        print(-1)
        return

    # Find minimum number of s1 copies needed
    # We'll use binary search on the number of copies
    def can_form(k):
        # Check if s2 is a subsequence of s1 repeated k times
        i = 0  # pointer for s2
        j = 0  # pointer for s1
        while i < len(s2):
            if j == len(s1):
                # Wrap around to the start of s1
                j = 0
            if s1[j] == s2[i]:
                i += 1
            j += 1
            # If we've gone through k full copies without finishing s2
            if j == len(s1) and k > 0:
                k -= 1
                j = 0
        return i == len(s2)

    # Binary search for minimum k
    left = 1
    right = len(s2)  # Maximum possible copies needed
    answer = -1

    while left <= right:
        mid = (left + right) // 2
        if can_form(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    print(answer)

