    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Find the maximum length of consecutive 1s we can get
    max_len = 0
    left = 0
    zeros = 0

    for right in range(n):
        if a[right] == 0:
            zeros += 1

        # If we have more zeros than allowed, move left pointer
        while zeros > k:
            if a[left] == 0:
                zeros -= 1
            left += 1

        # Update maximum length
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len
            # Track the best window
            best_left = left
            best_right = right

    # Output the result
    print(max_len)

    # Modify the array to show the best solution
    for i in range(n):
        if best_left <= i <= best_right:
            # If it's a 0 in the best window, change it to 1
            if a[i] == 0:
                print(1, end=' ')
            else:
                print(a[i], end=' ')
        else:
            print(a[i], end=' ')
    print()

if __name__ == "__main__":
    solve()

