import itertools

def solve():
    n = int(input())
    cards = input().split()

    # We need to find the minimum number of hints (colors and values) needed
    # to uniquely identify each card

    # Try all possible combinations of hints
    colors = set()
    values = set()
    for card in cards:
        colors.add(card[0])
        values.add(card[1])

    # Try all subsets of colors and values
    min_hints = n  # Worst case: we need to hint about each card individually

    # Try all possible combinations of hints
    for color_subset in itertools.chain.from_iterable(itertools.combinations(colors, r) for r in range(len(colors)+1)):
        for value_subset in itertools.chain.from_iterable(itertools.combinations(values, r) for r in range(len(values)+1)):

            # Check if this combination uniquely identifies all cards
            identified = {}
            for card in cards:
                # Get the set of hints this card belongs to
                hints = set()
                for color in color_subset:
                    if card[0] == color:
                        hints.add(color)
                for value in value_subset:
                    if card[1] == value:
                        hints.add(value)

                # If this card has been identified before with a different hint set, it's not unique
                if len(hints) > 1:
                    if tuple(sorted(hints)) in identified:
                        break
                identified[tuple(sorted(hints))] = card
            else:
                # All cards are uniquely identified
                min_hints = min(min_hints, len(color_subset) + len(value_subset))

    print(min_hints)

solve()
