    n = int(input())
    arr = list(map(int, input().split()))
    total = sum(arr)

    if total % 2 != 0:
        # Odd total, impossible to have equal sums, so output any arrangement
        print(' '.join(map(str, arr)))
    else:
        target = total // 2

        # Check if there's a way to split into two groups with equal sums
        if not can_split(arr, n, target):
            # No equal split, output any arrangement
            print(' '.join(map(str, arr)))
        else:
            # There is an equal split, check if there's a different split
            # Try to find a split where the sum is NOT target
            found = False

            # Try all possible splits
