import sys

def can_win(array, K, S):
    """Check if Vasya can win given array, K, and sum S."""
    n = len(array)

    # Generate all possible subarray sums
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + array[i]

    # Check if any subarray sum equals K or S-K
    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            sub_sum = prefix_sums[j] - prefix_sums[i]
            if sub_sum == K or sub_sum == S - K:
                return True

    return False

def solve(N, S):
    """Find an array and K such that Petya wins."""
    # Try the strategy: N-1 ones and one large element
    large = S - (N - 1)
    array = [1] * (N - 1) + [large]

    # Check if there exists a K such that neither K nor S-K is achievable
    for K in range(1, S + 1):
        if not can_win(array, K, S):
            return "YES", array, K

    return "NO", None, None

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

    N = int(data[0])
    S = int(data[1])

    result, array, K = solve(N, S)

    if result == "YES":
        print("YES")
        print(" ".join(map(str, array)))
        print(K)
    else:
        print("NO")
