import sys

def can_win(array, K, S, prefix_sums):
    """Check if Vasya can win given array, K, and sum S."""
    n = len(array)

    # Check if any subarray sum equals K or S-K
    for i in range(len(array) + 1):
        for j in range(i + 1, len(array) + 1):
            sub_sum = prefix_sums[j] - prefix_sums[i]
            if sub_sum == K or sub_sum == S - K:
                return True

    return False

def solve(N, S):
    large = S - (N - 1)
    array = [1] * (N - 1) + [large]
    prefix_sums = [0] * (N + 1)
    for i in range(N):
        prefix_sums[i + 1] = prefix_sums[i] + array[i]

    # Pick the largest K that is not achievable and is at least N to avoid small sums
    # Search backwards from S to N
    for K in range(S, N - 1, -1):
        if not can_win(array, K, S, prefix_sums):
            for k in range(1, S + 1):
                if not can_win(array, k, S, prefix_sums):
                    return "YES", array, k

    return "NO", None, None

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

    N = int(data[0])
    S = int(data[1])

    result, array, K = solve(N, S)

    if result == "YES":
        print("YES")
        if N > 1:
            print(" " + " ".join(map(str, array[:2])) + " {}".format(array[-1]), file=sys.stderr)
        else:
            print("{}".format(array[-1]))

        # Line breaks for stdout
        sys.stdout.write("YES\n")
        if array:
            sys.stdout.write(str(array[0]))
            for num in array[1:]:
                sys.stdout.write(f" {num}")
            sys.stdout.write("\n")
            sys.stdout.write(f"{K}\n")
    else:
        sys.stdout.write("NO\n")
