    n, m = map(int, input().split())
    strings = [input().strip() for _ in range(n)]

    # Generate candidate strings for each input string
    candidates = []
    for s in strings:
        # The string itself
        candidates.append(set([s]))

        # Strings that differ in exactly one position
        for i in range(m):
            # Try changing each character to all 26 lowercase letters
            for ch in "abcdefghijklmnopqrstuvwxyz":
                if ch != s[i]:
                    # Create a new string with character at position i changed to ch
                    new_s = s[:i] + ch + s[i+1:]
                    candidates[-1].add(new_s)

    # Find the intersection of all candidate sets
    common = candidates[0]
    for i in range(1, n):
        common &= candidates[i]

    if common:
        print(common.pop())
    else:
        print(-1)
