import math

def factorize(x):
    """Return a dictionary of prime factors and their exponents for x"""
    factors = {}

    # Check for small primes
    for i in range(2, int(math.isqrt(x)) + 1):
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x //= i

    # If remaining x is > 1, it's a prime
    if x > 1:
        factors[x] = factors.get(x, 0) + 1

    return factors

def solve():
    n = int(input())

    # Dictionary to accumulate prime exponents
    prime_exponents = {}

    for _ in range(n):
        a = int(input())

        # Get prime factors of a
        factors = factorize(a)

        # Accumulate exponents
        for p, e in factors.items():
            prime_exponents[p] = prime_exponents.get(p, 0) + e

    # Calculate number of divisors
    MOD = 998244353
    result = 1

    for e in prime_exponents.values():
        result = (result * (e + 1)) % MOD

    print(result)

if __name__ == "__main__":
    solve()
"}

