import math

def is_perfect_power(x, power):
    """Check if x is a perfect power (e.g., x = y^power)"""
    root = round(x ** (1.0 / power))
    return root ** power == x

def factorize(x):
    """Return a dictionary of prime factors and their exponents for x"""
    factors = {}

    # Check if x is a perfect square
    if is_perfect_power(x, 2):
        sqrt_x = int(math.isqrt(x))
        # Check if it's also a perfect cube
        if is_perfect_power(sqrt_x, 3):
            cube_root = int(round(sqrt_x ** (1.0 / 3)))
            factors[cube_root] = 4
        # Check if it's also a perfect fourth power
        elif is_perfect_power(sqrt_x, 4):
            fourth_root = int(round(sqrt_x ** (1.0 / 4)))
            factors[fourth_root] = 6
        else:
            factors[sqrt_x] = 2

    # Check if x is a perfect cube
    elif is_perfect_power(x, 3):
        cube_root = int(round(x ** (1.0 / 3)))
        # Check if it's also a perfect fourth power
        if is_perfect_power(cube_root, 4):
            fourth_root = int(round(cube_root ** (1.0 / 4)))
            factors[fourth_root] = 5
        else:
            factors[cube_root] = 3

    # Check if x is a perfect fourth power
    elif is_perfect_power(x, 4):
        fourth_root = int(round(x ** (1.0 / 4)))
        factors[fourth_root] = 4

    # If none of the above, it must be p*q
    else:
        # Find one prime factor by trial division
        for i in range(2, int(math.isqrt(x)) + 1):
            if x % i == 0:
                # Found a prime factor
                p = i
                q = x // p
                # Check if q is prime
                if q > 1 and all(q % j != 0 for j in range(2, int(math.isqrt(q)) + 1)):
                    factors[p] = 1
                    factors[q] = 1
                break

    return factors

def solve():
    n = int(input())

    # Dictionary to accumulate prime exponents
    prime_exponents = {}

    for _ in range(n):
        a = int(input())

        # Get prime factors of a
        factors = factorize(a)

        # Accumulate exponents
        for p, e in factors.items():
            prime_exponents[p] = prime_exponents.get(p, 0) + e

    # Calculate number of divisors
    MOD = 998244353
    result = 1

    for e in prime_exponents.values():
        result = (result * (e + 1)) % MOD

    print(result)

if __name__ == "__main__":
    solve()
