import sys
from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [1] * (n + 1)
    mst_edges = []
    for a, b, e in edges:
        if union(parent, rank, a, b):
            mst_edges.append((a, b, e))
    return mst_edges

def build_tree(n, edges):
    tree = defaultdict(list)
    for a, b, e in edges:
        tree[a].append((b, e))
        tree[b].append((a, e))
    return tree

def find_min_path(n, tree, u, v):
    # Find minimum weight on path from u to v using BFS
    visited = {u: (u, float('inf'))}  # node: (parent, min_weight_on_path)
    queue = [u]
    while queue:
        node = queue.pop(0)
        if node == v:
            break
        for neighbor, weight in tree[node]:
            if neighbor not in visited:
                new_min = min(visited[node][1], weight)
                visited[neighbor] = (node, new_min)
                queue.append(neighbor)
    return visited[v][1]

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        e = int(next(it))
        edges.append((a, b, e))

    mst_edges = kruskal(n, edges)

    # Build tree from MST
    mst_tree = build_tree(n, mst_edges)

    # Find E_max for each non-MST edge
    result = []
    for a, b, e in edges:
        if (a, b, e) not in mst_edges and (b, a, e) not in mst_edges:
            min_on_path = find_min_path(n, mst_tree, a, b)
            result.append(str(min_on_path))

    sys.stdout.write("\n".join(result))

if __name__ == "__main__":
    solve()
"}

