                    a //= 2
                    exp += 1
                prime_exponents[2] = prime_exponents.get(2, 0) + exp
            if a % 3 == 0:
                exp = 0
                while a % 3 == 0:
                    a //= 3
                    exp += 1
                prime_exponents[3] = prime_exponents.get(3, 0) + exp
            if a % 5 == 0:
