import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Compute prefix counts: prefix_count[value][i] = count of value in a[0..i]
    # Actually, we can just compute for each position
    prefix_count = {}
    for i in range(n):
        val = a[i]
        if val not in prefix_count:
            prefix_count[val] = [0] * n
        prefix_count[val][i] = prefix_count[val][i-1] + 1 if i > 0 else 1

    # Compute suffix counts: suffix_count[value][i] = count of value in a[i..n-1]
    suffix_count = {}
    for i in range(n-1, -1, -1):
        val = a[i]
        if val not in suffix_count:
            suffix_count[val] = [0] * n
        suffix_count[val][i] = suffix_count[val][i+1] + 1 if i < n-1 else 1

    # Count valid pairs
    result = 0
    for i in range(n):
        for j in range(i+1, n):
            val_i = a[i]
            val_j = a[j]
            # f(1, i, ai) is prefix_count[val_i][i-1] + 1 (since we include a[i])
            # f(j, n, aj) is suffix_count[val_j][j]
            if prefix_count[val_i][i] > suffix_count[val_j][j]:
                result += 1

    print(result)

if __name__ == "__main__":
