import sys

def is_good(table):
    """Check if the table is good"""
    n = len(table)
    for i in range(n - 1):
        row1 = table[i]
        row2 = table[i + 1]
        # Compare row1 and row2 lexicographically
        for c1, c2 in zip(row1, row2):
            if c1 > c2:
                return False
            elif c1 < c2:
                break
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    table = []
    idx = 2
    for _ in range(n):
        row = data[idx:idx + m]
        table.append(row)
        idx += m

    # Try all possible ways of removing columns from left and right
    min_removals = m

    for left_remove in range(m + 1):
        for right_remove in range(m + 1 - left_remove):
            # Remove left_remove columns from the left
            # Remove right_remove columns from the right
            if left_remove + right_remove >= m:
                continue

            kept_columns = set(range(left_remove, m - right_remove))
            new_table = []
            for row in table:
                new_row = [row[i] for i in kept_columns]
                new_table.append(new_row)

            if is_good(new_table):
                min_removals = min(min_removals, left_remove + right_remove)

    print(min_removals)

