def reverse_shell_game(n, x):
    """Reverse the shell game moves in O(1)"""
    # Count how many full pairs of moves we have
    pairs = n // 2
    extra = n % 2

    # For each pair, the effect is:
    # 0 → 2, 1 → 1, 2 → 0
    # So after k pairs, the result depends on k mod 3
    k_mod_3 = pairs % 3

    # Apply the effect of k_mod_3 pairs
    if k_mod_3 == 0:
        pass  # no change
    elif k_mod_3 == 1:
        if x == 0:
            x = 2
        elif x == 2:
            x = 0
    else:  # k_mod_3 == 2
        if x == 0:
            x = 0
        elif x == 1:
            x = 1
        elif x == 2:
            x = 2

    # Apply the effect of the extra move (if n is odd)
    if extra:
        if x == 0:
            x = 1
        elif x == 1:
            x = 0

    return x

def solve():
    n = int(input())
    x = int(input())

    result = reverse_shell_game(n, x)
