    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Compute prefix counts
    prefix_counts = [0] * n
    last = {}
    for i in range(n):
        val = a[i]
        if val in last:
            prefix_counts[i] = last[val] + 1
        else:
            prefix_counts[i] = 1
        last[val] = prefix_counts[i]

    # Compute suffix counts
    suffix_counts = [0] * n
    last = {}
    for i in range(n-1, -1, -1):
        val = a[i]
        if val in last:
            suffix_counts[i] = last[val] + 1
        else:
            suffix_counts[i] = 1
        last[val] = suffix_counts[i]

    # Compress values
    values = set(prefix_counts + suffix_counts)
    values = sorted(values)
    compress = {v: i+1 for i, v in enumerate(values)}

    # Fenwick Tree
    class FenwickTree:
        def __init__(self, size):
            self.size = size
            self.tree = [0] * (self.size + 1)

        def update(self, index, delta=1):
            while index <= self.size:
                self.tree[index] += delta
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

    ft = FenwickTree(len(values))

    # Process from right to left
    result = 0
    for i in range(n-1, -1, -1):
        # Count how many suffix counts are less than prefix_counts[i]
        # We need suffix_counts[j] < prefix_counts[i] for j > i
        # So we query for the compressed value of prefix_counts[i] - 1
