import sys

def lcs_length(a, b):
    """Compute the length of the longest common subsequence between a and b"""
    m, n = len(a), len(b)
    # Create a 2D array of (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[m][n]

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        a = sys.stdin.readline().strip()
        b = sys.stdin.readline().strip()

        lcs = lcs_length(a, b)
        operations = len(a) + len(b) - 2 * lcs

        print(operations)

if __name__ == "__main__":
    solve()
"}

