import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    strings = data[1:1+n]

    # Check if all strings have the same length
    length = len(strings[0])
    for s in strings[1:]:
        if len(s) != length:
            print(-1)
            return

    # Generate all rotations for each string
    rotations = []
    for s in strings:
        rot_set = set()
        for i in range(length):
            rotated = s[i:] + s[:i]
            rot_set.add(rotated)
        rotations.append(rot_set)

    # Find common rotations
    common_rotations = rotations[0]
    for i in range(1, n):
        common_rotations &= rotations[i]

    if not common_rotations:
        print(-1)
        return

    # Find minimum total rotations
    min_total = float('inf')
    for target in common_rotations:
        total = 0
        for s in strings:
            # Find minimum rotations to reach target from s
            for i in range(length):
                rotated = s[i:] + s[:i]
                if rotated == target:
                    total += i
                    break
        min_total = min(min_total, total)

    print(min_total)

if __name__ == "__main__":
    solve()
